INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_MIRAVALLE_MARIOLOGY','secondary scholarship','Mark Miravalle (ed.), Mariology: A Guide for Priests, Deacons, Seminarians, and Consecrated Persons (Seat of Wisdom Books / Queenship, 2007)','Catholic Mariology — Marian titles, dogmas, and approved apparitions')
INSERT INTO _e VALUES
 ('ENT_MARY_TITLES','Marian Titles and Devotions','Collective','Marian devotion','Christian','reception','B','Organizing hub collective for the historic titles, devotional images, and approved apparitions of the Blessed Virgin Mary across Catholic and Eastern devotion; not a separate figure.'),
 ('ENT_MARY_ROSARY','Our Lady of the Rosary','Marian title/apparition','Marian title','Christian','reception','B','Marian title tied to the Dominican Rosary devotion (trad. ascribed to St Dominic); feast (orig. Our Lady of Victory) instituted by Pius V after Lepanto, 1571; attested in Counter-Reformation Catholic devotion and liturgy.'),
 ('ENT_MARY_MOUNT_CARMEL','Our Lady of Mount Carmel','Marian title/apparition','Marian title','Christian','reception','B','Patronal title of the Carmelite Order, linked to the trad. 1251 vision of St Simon Stock and the Brown Scapular; feast 16 July; attested in medieval Carmelite tradition and Mariology.'),
 ('ENT_MARY_BROWN_SCAPULAR','Brown Scapular of Our Lady of Mount Carmel','Marian title/apparition','Marian devotion','Christian','reception','C','Carmelite sacramental devotion (the scapular), trad. given by Our Lady of Mount Carmel to St Simon Stock (1251); a devotional object/practice rather than a figure; attested in Carmelite and Counter-Reformation devotion.'),
 ('ENT_MARY_SORROWS','Our Lady of Sorrows','Marian title/apparition','Marian title','Christian','reception','B','Marian title (Mater Dolorosa) contemplating the Seven Sorrows of Mary; medieval devotion fostered by the Servite Order; feast 15 September; attested in medieval and modern Catholic Mariology.'),
 ('ENT_MARY_PERPETUAL_HELP','Our Lady of Perpetual Help','Marian title/apparition','Marian title','Christian','reception','B','Marian title centered on a Cretan-Byzantine icon (15th c.) entrusted by Pius IX to the Redemptorists (1866); widely diffused modern devotion; attested in icon history and Catholic Mariology.'),
 ('ENT_MARY_CZESTOCHOWA','Our Lady of Częstochowa (the Black Madonna)','Marian title/apparition','Marian title','Christian','reception','B','Venerated icon at the Jasna Góra monastery, Częstochowa, Poland; the ''Black Madonna,'' national palladium of Poland; crowned 1717; attested in Polish religious history and Mariology.'),
 ('ENT_MARY_WALSINGHAM','Our Lady of Walsingham','Marian title/apparition','Marian title','Christian','reception','C','English Marian shrine at Walsingham, Norfolk, founded after a vision of Richeldis de Faverches (trad. 1061); major medieval pilgrimage, suppressed at the Reformation, revived 20th c.; attested in English ecclesiastical history.'),
 ('ENT_MARY_LORETO','Our Lady of Loreto','Marian title/apparition','Marian title','Christian','reception','C','Marian title attached to the Holy House of Loreto (Marche, Italy), trad. translated from Nazareth; namesake of the Litany of Loreto; patroness of aviators; attested in medieval and modern Catholic devotion.'),
 ('ENT_MARY_MERCY','Our Lady of Mercy (Mercedes)','Marian title/apparition','Marian title','Christian','reception','C','Marian title (Our Lady of Ransom / la Merced) tied to the founding of the Mercedarian Order by St Peter Nolasco (1218) for ransoming captives; feast 24 September; attested in medieval Iberian Catholic devotion.'),
 ('ENT_MARY_AKITA','Our Lady of Akita','Marian title/apparition','Marian apparition','Christian','reception','C','Reported apparitions/locutions and a weeping statue to Sr. Agnes Sasagawa, Akita, Japan (1973); declared worthy of belief by the local bishop (1984); attested in modern Catholic apparition reports.'),
 ('ENT_MARY_ZEITOUN','Our Lady of Zeitoun','Marian title/apparition','Marian apparition','Christian','reception','C','Mass-witnessed luminous apparitions over the Coptic Orthodox Church of the Virgin in Zeitoun, Cairo (1968-71); approved by the Coptic Orthodox Patriarchate; attested in Coptic and broader Marian sources.');
